/* The same interactive widgets work in their editor and on the canvas. */
(function(){'use strict';const T=()=>NotaMisc,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let serial=0,boardCleanups=[];
function paletteHTML(m){return `<fieldset class="toy-options"><legend>Color palette</legend><div class="toy-palettes">${T().palettes.map(([id,name,base])=>`<button type="button" data-toy-palette="${id}" aria-label="${name} palette" aria-pressed="${m.palette===id}"><span style="background:linear-gradient(135deg,${T().colors({palette:id}).light},${base} 45%,${T().colors({palette:id}).dark})"></span></button>`).join('')}</div><label class="toy-custom">Custom color<input type="color" data-toy-color value="${m.palette==='custom'?m.color:T().colors(m).base}" aria-label="Custom widget color"></label></fieldset>`;}
function stage(mode,m,id){if(mode==='spinner')return `<div class="toy-stage"><button type="button" class="spinner-touch" data-spinner-touch aria-label="Spin the fidget spinner. You can also flick or drag it.">${T().spinnerSVG(m,id)}</button></div><div class="toy-actions"><button type="button" class="primary" data-spinner-spin>Spin</button><button type="button" class="secondary" data-spinner-stop disabled>Stop</button></div><p class="toy-state" data-toy-status role="status">Tap to spin, or flick the shape.</p>`;return `<div class="dice-tray" data-dice-tray></div><div class="dice-total"><span data-dice-caption>Ready to roll</span><strong data-dice-total>—</strong></div><p class="dice-breakdown" data-dice-breakdown></p><div class="toy-actions"><button type="button" class="primary" data-dice-roll>Roll dice</button></div><p class="toy-state" data-toy-status role="status"></p>`;}
function widgetHTML(n,editor=false){const mode=n.inputMode,m=n[mode],id=(++serial).toString(36),color=T().colors(m);return `<section class="misc-widget" data-misc-mode="${mode}" style="--toy-base:${color.base};--toy-light:${color.light};--toy-dark:${color.dark}" ${editor?`id="${mode}-widget"`:''}>${editor?`<p class="misc-lead">${mode==='spinner'?'A little room to unwind. Tap, flick, or drag your spinner.':'Pick your dice, choose how many, and let them tumble.'}</p>`:`<h2>${esc(n.title)}</h2>`}${stage(mode,m,id)}${editor?mode==='spinner'?`<fieldset class="toy-options"><legend>Shape</legend><div class="toy-shapes">${T().shapes.map(([shape,label])=>`<button type="button" data-spinner-shape="${shape}" aria-pressed="${m.shape===shape}">${T().spinnerSVG({...m,shape},id+'-'+shape)}<span>${label}</span></button>`).join('')}</div></fieldset>${paletteHTML(m)}`:`<fieldset class="toy-options"><legend>Choose your dice</legend><div class="dice-pool">${T().sides.map(s=>`<div class="dice-pick"><strong>d${s}</strong><div class="dice-stepper"><button type="button" data-dice-less="${s}" aria-label="Remove a d${s}">−</button><input type="number" inputmode="numeric" min="0" max="${T().MAX_EACH}" step="1" data-dice-quantity="${s}" value="${m.pool[s]}" aria-label="d${s} quantity"><button type="button" data-dice-more="${s}" aria-label="Add a d${s}">+</button></div></div>`).join('')}</div><p class="hint" data-dice-count></p><p class="hint">d100 gives a percentile result from 1 to 100. Up to ${T().MAX_EACH} of each type and ${T().MAX_DICE} dice in one roll.</p><div class="toy-actions"><button type="button" class="secondary" data-dice-set>Classic seven</button><button type="button" class="secondary" data-dice-reset>Clear selection</button></div></fieldset>${paletteHTML(m)}<details class="dice-history"><summary>Recent rolls <span data-dice-history-count></span></summary><ol data-dice-history></ol></details>`:''}</section>`;}
function mount(root,n,persist,flush=()=>Promise.resolve()){const mode=n.inputMode,m=n[mode],$=s=>root.querySelector(s),$$=s=>[...root.querySelectorAll(s)],status=$('[data-toy-status]');let alive=true,finishTimer=null,frame=0,speed=0,angle=0,previous=0,drag=null,suppressClickUntil=0,rolling=false;
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 const setStatus=text=>{if(alive)status.textContent=text;};
 const stop=()=>{cancelAnimationFrame(frame);frame=0;speed=0;if(mode==='spinner'){$('[data-spinner-stop]').disabled=true;root.dataset.spinning='false';setStatus('At rest. Tap or flick to spin.');}};
 const showAngle=()=>{$('[data-spinner-rotor]')?.setAttribute('transform','rotate('+angle+' 100 100)');};
 const tick=now=>{if(!alive||!root.isConnected||document.hidden){stop();return;}const dt=Math.min(50,Math.max(0,now-previous))/1000;previous=now;angle=(angle+speed*dt)%360;speed*=Math.exp(-dt*(reduced()?1.2:.26));showAngle();if(Math.abs(speed)<8){stop();return;}frame=requestAnimationFrame(tick);};
 const spin=(velocity=1100)=>{stop();speed=Math.max(-2200,Math.min(2200,velocity));if(reduced())speed=Math.max(-240,Math.min(240,speed));previous=performance.now();root.dataset.spinning='true';$('[data-spinner-stop]').disabled=false;setStatus('Spinning. Flick again or choose Stop.');frame=requestAnimationFrame(tick);};
 const recolor=()=>{const p=T().colors(m);root.style.setProperty('--toy-base',p.base);root.style.setProperty('--toy-light',p.light);root.style.setProperty('--toy-dark',p.dark);$$('[data-toy-palette]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.toyPalette===m.palette)));const color=$('[data-toy-color]');if(color)color.value=p.base;if(mode==='spinner'){$('[data-spinner-touch]').innerHTML=T().spinnerSVG(m,'active-'+(++serial));showAngle();$$('[data-spinner-shape]').forEach(b=>{b.innerHTML=T().spinnerSVG({...m,shape:b.dataset.spinnerShape},'shape-'+(++serial))+'<span>'+T().shapes.find(s=>s[0]===b.dataset.spinnerShape)[1]+'</span>';b.setAttribute('aria-pressed',String(b.dataset.spinnerShape===m.shape));});}else showDice(false);};
 const refreshPool=()=>{if(mode!=='dice')return;const count=T().poolCount(m.pool);$('[data-dice-roll]').disabled=rolling||!count;$('[data-dice-roll]').textContent=rolling?'Rolling…':'Roll '+count+' '+(count===1?'die':'dice');$$('[data-dice-quantity]').forEach(el=>{el.value=m.pool[el.dataset.diceQuantity];el.disabled=rolling;});$$('[data-dice-less]').forEach(b=>b.disabled=rolling||!m.pool[b.dataset.diceLess]);$$('[data-dice-more]').forEach(b=>b.disabled=rolling||m.pool[b.dataset.diceMore]>=T().MAX_EACH||count>=T().MAX_DICE);$$('[data-dice-set],[data-dice-reset],[data-toy-palette],[data-toy-color]').forEach(b=>b.disabled=rolling);const countEl=$('[data-dice-count]');if(countEl)countEl.textContent=count+' '+(count===1?'die':'dice')+' selected · '+(T().sides.filter(s=>m.pool[s]).map(s=>m.pool[s]+'d'+s).join(' + ')||'Choose at least one die');};
 function showDice(animate){const latest=m.history[0],tray=$('[data-dice-tray]');if(!tray)return;tray.classList.remove('rolling');tray.innerHTML=latest?latest.results.map((d,i)=>`<div class="dice-token" style="--die-index:${i%8}" aria-label="d${d.sides} rolled ${d.value}">${T().dieSVG(d.sides,d.value,m,'result-'+(++serial))}<small>d${d.sides}</small></div>`).join(''):`<div class="dice-token">${T().dieSVG(20,'?',m,'ready-'+(++serial))}<small>Your next roll</small></div>`;if(animate){void tray.offsetWidth;tray.classList.add('rolling');tray.setAttribute('aria-hidden','true');$('[data-dice-caption]').textContent='Rolling';$('[data-dice-total]').textContent='…';$('[data-dice-breakdown]').textContent='';}else{tray.removeAttribute('aria-hidden');$('[data-dice-caption]').textContent=latest?'Last roll · Total':'Ready to roll';$('[data-dice-total]').textContent=latest?latest.total:'—';$('[data-dice-breakdown]').textContent=latest?T().summary(latest):'Choose your dice in the editor.';}
 const list=$('[data-dice-history]');if(list){$('[data-dice-history-count]').textContent='('+m.history.length+')';list.innerHTML=m.history.map(r=>`<li><strong>Total ${r.total}</strong><time>${esc(new Date(r.at).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'}))}</time><p>${esc(T().summary(r))}</p></li>`).join('')||'<li>Your last 20 rolls will appear here.</li>';}}
 const finishRoll=()=>{clearTimeout(finishTimer);finishTimer=null;if(!alive)return;rolling=false;showDice(false);refreshPool();const r=m.history[0];if(r)setStatus('Rolled '+r.results.length+' '+(r.results.length===1?'die':'dice')+'. Total '+r.total+'. '+T().summary(r));};
 const doRoll=async()=>{if(rolling||!T().poolCount(m.pool))return;let result;try{result=T().roll(m.pool);}catch{setStatus('Could not roll. Try again.');return;}m.history.unshift(result);m.history=m.history.slice(0,20);rolling=true;setStatus('Rolling…');refreshPool();persist();await Promise.resolve().then(flush).catch(()=>{});if(!alive)return;showDice(true);finishTimer=setTimeout(finishRoll,reduced()?80:1050);};
 const interactive=e=>{if(e.target.closest('button,input,select,summary'))e.stopPropagation();};root.addEventListener('click',interactive);
 if(mode==='spinner'){
  root.dataset.spinning='false';const face=$('[data-spinner-touch]');face.onclick=()=>{if(performance.now()<suppressClickUntil)return;spin();};$('[data-spinner-spin]').onclick=()=>spin();$('[data-spinner-stop]').onclick=stop;
  face.onpointerdown=e=>{if(e.button!==0)return;stop();const r=face.getBoundingClientRect();drag={id:e.pointerId,cx:r.left+r.width/2,cy:r.top+r.height/2,last:0,at:performance.now(),velocity:0,distance:0};drag.last=Math.atan2(e.clientY-drag.cy,e.clientX-drag.cx);face.setPointerCapture(e.pointerId);};
  face.onpointermove=e=>{if(!drag||e.pointerId!==drag.id)return;e.preventDefault();const a=Math.atan2(e.clientY-drag.cy,e.clientX-drag.cx),delta=Math.atan2(Math.sin(a-drag.last),Math.cos(a-drag.last))*180/Math.PI,now=performance.now();drag.velocity=delta/Math.max(8,now-drag.at)*1000;drag.distance+=Math.abs(delta);drag.last=a;drag.at=now;angle=(angle+delta)%360;showAngle();};
  face.onpointerup=e=>{if(!drag||e.pointerId!==drag.id)return;const d=drag;drag=null;if(d.distance>4){suppressClickUntil=performance.now()+350;spin(performance.now()-d.at>160?150:(d.velocity||150));}if(face.hasPointerCapture(e.pointerId))face.releasePointerCapture(e.pointerId);};face.onpointercancel=()=>{drag=null;suppressClickUntil=0;stop();};face.onlostpointercapture=()=>{drag=null;};
  $$('[data-spinner-shape]').forEach(b=>b.onclick=()=>{stop();m.shape=b.dataset.spinnerShape;recolor();persist();});
 }else{
  $('[data-dice-roll]').onclick=doRoll;
  const setQuantity=(s,value)=>{if(rolling)return;const next={...m.pool,[s]:value};if(!T().validPool(next)){setStatus('Choose 0–'+T().MAX_EACH+' of each type, up to '+T().MAX_DICE+' dice total.');refreshPool();return;}m.pool=next;refreshPool();persist();setStatus(T().poolCount(m.pool)?'Ready when you are.':'Choose at least one die.');};
  $$('[data-dice-more]').forEach(b=>b.onclick=()=>setQuantity(b.dataset.diceMore,m.pool[b.dataset.diceMore]+1));$$('[data-dice-less]').forEach(b=>b.onclick=()=>setQuantity(b.dataset.diceLess,m.pool[b.dataset.diceLess]-1));$$('[data-dice-quantity]').forEach(el=>el.onchange=()=>setQuantity(el.dataset.diceQuantity,el.value===''?0:Number(el.value)));
  const set=$('[data-dice-set]'),reset=$('[data-dice-reset]');if(set)set.onclick=()=>{m.pool=Object.fromEntries(T().sides.map(s=>[s,1]));refreshPool();persist();setStatus('One of each of the seven dice selected.');};if(reset)reset.onclick=()=>{m.pool=Object.fromEntries(T().sides.map(s=>[s,0]));refreshPool();persist();setStatus('Choose at least one die.');};showDice(false);refreshPool();
 }
 $$('[data-toy-palette]').forEach(b=>b.onclick=()=>{if(rolling)return;m.palette=b.dataset.toyPalette;recolor();persist();});const custom=$('[data-toy-color]');if(custom)custom.oninput=()=>{if(rolling||!/^#[0-9a-f]{6}$/i.test(custom.value))return;m.palette='custom';m.color=custom.value;recolor();persist();};
 const visibility=()=>{if(document.hidden){if(mode==='spinner'){drag=null;stop();}else if(rolling)finishRoll();}};document.addEventListener('visibilitychange',visibility);
 return ()=>{alive=false;cancelAnimationFrame(frame);clearTimeout(finishTimer);document.removeEventListener('visibilitychange',visibility);root.removeEventListener('click',interactive);};
}
function editor(n,c){const mode=n.inputMode;NotaModeEditors.shell(n,c,mode==='spinner'?'Fidget Spinner':'Dice Tray',widgetHTML(n,true));const persist=NotaModeEditors.common(n,c,()=>T().html(mode,n[mode]));const cleanup=mount(document.querySelector('#'+mode+'-widget'),n,persist,c.flush);c.cleanup(cleanup);c.icons();}
window.NotaMiscUI={card:n=>widgetHTML(n),clearBoard:()=>{boardCleanups.forEach(fn=>fn());boardCleanups=[];},mountBoard:(host,items,save,flush)=>{host.querySelectorAll('.misc-widget').forEach(root=>{const n=items.find(n=>n.id===root.closest('.card').dataset.id);if(n)boardCleanups.push(mount(root,n,()=>{n.html=T().html(n.inputMode,n[n.inputMode]);save(n);},flush));});}};
window.NotaMiscEditors={spinner:editor,dice:editor};
})();
